const normArr=xs=>[...new Set((xs||[]).map(String))].sort();
const validId=v=>typeof v==='string'&&/^[a-z0-9][a-z0-9._-]*$/.test(v);
const rel=(root,p)=>path.relative(root,p).replaceAll('\\','/');
const policyPath=r=>path.join(r,'.aledevos','skillsystem','policies','skill-policy.json');
