function installedAdapters(r){const p=projectConfigPath(r);if(!fs.existsSync(p))return[];const q=readJson(p),xs=Array.isArray(q.adapters)?q.adapters:(q.adapter?[q.adapter]:[]);return normArr(xs.map(normalizeAdapter).filter(Boolean))}
function resolveAdapter(r,a=null){const requested=normalizeAdapter(a);if(requested)return requested;const xs=installedAdapters(r);if(xs.length===1)return xs[0];if(xs.length===0)fail('SKILL_ADAPTER_NOT_CONFIGURED',30);fail('SKILL_ADAPTER_REQUIRED_FOR_MULTI_ADAPTER_PROJECT',31)}
const estimateTokensText=s=>Math.max(1,Math.ceil(Buffer.byteLength(String(s),'utf8')/4));
function loadPolicy(r){const p=policyPath(r);if(!fs.existsSync(p))fail(`SKILL_POLICY_NOT_FOUND: ${p}`,20);return readJson(p)}
