function verifyRoute(projectRoot,taskId){const f=path.join(routesDir(projectRoot),`${String(taskId).replace(/[^a-zA-Z0-9._-]/g,'_')}.json`);if(!fs.existsSync(f))return{valid:false,errors:['route_missing']};const o=readJson(f),e=[];if(o?.integrity?.payload_sha256!==sha256Object(withoutIntegrity(o)))e.push('route_integrity_mismatch');const adapter=resolveAdapter(projectRoot,o.adapter),rv=verifyRegistry(projectRoot,adapter);if(!rv.valid)e.push('registry_invalid');else{const reg=readJson(registryPath(projectRoot,adapter)),by=new Map((reg.skills||[]).map(x=>[x.id,x]));for(const x of o.selected||[]){const s=by.get(x.id);if(!s||!s.runtime?.usable)e.push(`selected_skill_unavailable:${x.id}`)}}return{valid:e.length===0,errors:e,task_id:taskId,adapter,route:f};}

function artifactFile(dirFn,r,id){return path.join(dirFn(r),`${safeTaskId(id)}.json`)}
function verifySealedFile(fp,kind){if(!fs.existsSync(fp))return{valid:false,errors:[`${kind}_missing`]};const o=readJson(fp),e=[];if(o?.integrity?.payload_sha256!==sha256Object(withoutIntegrity(o)))e.push(`${kind}_integrity_mismatch`);return{valid:e.length===0,errors:e,artifact:o,path:fp};}
function loadContextPolicy(projectRoot){const p=contextPolicyPath(projectRoot);if(!fs.existsSync(p))fail(`CONTEXT_POLICY_NOT_FOUND: ${p}`,60);return readJson(p);}
function agentTargetBudget(ctx,profileName,agent){const rp=ctx?.runtime_profiles?.[profileName];if(!rp)fail(`UNKNOWN_CONTEXT_PROFILE: ${profileName}`,61);const ap=ctx?.agent_budgets?.[agent]||ctx?.agent_budgets?.default;if(!ap)fail(`UNKNOWN_AGENT_BUDGET: ${agent}`,62);const reserve=Math.max(Number(rp.max_output_tokens||0),Number(rp.native_compaction_buffer_tokens||0));const usable=Math.max(0,Number(rp.context_window||0)-reserve);const target=Math.min(Number(ap.max_target_tokens||usable),Math.floor(usable*Number(ap.target_ratio||1)));return{context_window:rp.context_window,reserve_tokens:reserve,usable_input_tokens:usable,agent_target_tokens:target};}
function compositionPolicy(p){return p.composition||{max_composed_skills:p.max_route_skills||8,expand_dependencies:true,fail_on_missing_dependency:true,fail_on_conflict:true,fail_on_cycle:true};}
function loadPolicy3(p){return p.instruction_loading||{max_ratio_of_agent_target:.35,max_instruction_tokens:8000,max_single_skill_tokens:5000,fail_closed_on_budget_exceeded:true,whole_skill_only:true};}
